    'devops-docker_k8s-s1-set1' => [
        [
            'text' => 'Explain the Linux kernel primitives underpinning Docker containers: Namespaces (pid, net, ipc, mnt, uts, user) and Control Groups (cgroups v1/v2). How do they provide process isolation and resource limitation?',
            'category' => 'technical',
